    '<strong>%1$s</strong> (%2$s) has subscribed successfully.' => '<strong>%1$s</strong> (%2$s) pomyślnie zasubskrybował(-a).',
    'Preko 98 posto aloe vere' => 'Ponad 98 procent aloesu',
